<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$adminUser=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$adminPassword=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';
$admin=new mysqli($host,$adminUser,$adminPassword,'',$port);$token=bin2hex(random_bytes(5));$database='t_dml_probe_'.$token;$otherDatabase='t_dml_other_'.$token;$users=['dml_'.$token,'create_'.$token,'trigger_'.$token,'view_'.$token,'global_'.$token,'column_'.$token];
function rdpCount(mysqli$db):int{$grantee="CONCAT(QUOTE(SUBSTRING_INDEX(CURRENT_USER(),'@',1)),'@',QUOTE(SUBSTRING_INDEX(CURRENT_USER(),'@',-1)))";$sql="SELECT (SELECT COUNT(*)<>1 OR COALESCE(SUM(PRIVILEGE_TYPE='USAGE'),0)<>1 FROM information_schema.USER_PRIVILEGES WHERE GRANTEE={$grantee})+(SELECT COUNT(*)<>4 OR COALESCE(SUM(TABLE_SCHEMA=DATABASE() AND PRIVILEGE_TYPE IN ('SELECT','INSERT','UPDATE','DELETE')),0)<>4 OR COUNT(DISTINCT PRIVILEGE_TYPE)<>4 FROM information_schema.SCHEMA_PRIVILEGES WHERE GRANTEE={$grantee})+(SELECT COUNT(*)<>0 FROM information_schema.TABLE_PRIVILEGES WHERE GRANTEE={$grantee})+(SELECT COUNT(*)<>0 FROM information_schema.COLUMN_PRIVILEGES WHERE GRANTEE={$grantee})";return(int)$db->query($sql)->fetch_column();}
try{$admin->query("CREATE DATABASE `{$database}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$admin->query("CREATE DATABASE `{$otherDatabase}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$admin->query("CREATE TABLE `{$otherDatabase}`.extra_data(id INT PRIMARY KEY,secret_value INT)");foreach($users as$user){$admin->query("CREATE USER `{$user}`@'%' IDENTIFIED BY 'Synthetic-Probe-2026!'");$admin->query("GRANT SELECT,INSERT,UPDATE,DELETE ON `{$database}`.* TO `{$user}`@'%'");}$admin->query("GRANT CREATE ON `{$database}`.* TO `{$users[1]}`@'%'");$admin->query("GRANT TRIGGER ON `{$database}`.* TO `{$users[2]}`@'%'");$admin->query("GRANT CREATE VIEW ON `{$database}`.* TO `{$users[3]}`@'%'");$admin->query("GRANT SELECT ON *.* TO `{$users[4]}`@'%'");$admin->query("GRANT SELECT(secret_value) ON `{$otherDatabase}`.extra_data TO `{$users[5]}`@'%'");
    $connections=[];try{foreach($users as$user)$connections[$user]=new mysqli($host,$user,'Synthetic-Probe-2026!',$database,$port);assertSameValue(0,rdpCount($connections[$users[0]]),'runbook probe accepts exact DML-only account');foreach(array_slice($users,1)as$user)assertSameValue(true,rdpCount($connections[$user])>0,"runbook probe rejects extra privilege for {$user}");}finally{foreach($connections as$connection)$connection->close();}echo"PASS: production runbook exact DML privilege probe sensitivity\n";
}finally{foreach($users as$user)try{$admin->query("DROP USER IF EXISTS `{$user}`@'%'");}catch(Throwable){}try{$admin->query("DROP DATABASE IF EXISTS `{$database}`");$admin->query("DROP DATABASE IF EXISTS `{$otherDatabase}`");}finally{$admin->close();}}
